  // =================================================================================
  // 2. MATHEMATICS (ගණිතය)
  // =================================================================================
  private fun getMathSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    return when (q % 12) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) සංඛ්‍යා රටාවේ පළමු පදය a = 4 සහ පොදු වෙනස d = 3 නම් n වන පදය Tn සොයන්න.", 3, "Tn = a + (n-1)d = 4 + (n-1)3 = 3n + 1.", listOf("Tn = 3n + 1 (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "එම සමාන්තර ශ්‍රේඪියේ 20 වන පදය T20 ගණනය කරන්න.", 4, "T20 = 3(20) + 1 = 61.", listOf("T20 = 61 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "පළමු පද 15යේ එකතුව S15 සූත්‍රය Sn = n/2 [2a + (n-1)d] මඟින් සොයන්න.", 4, "S15 = 15/2 [2(4) + 14(3)] = 15/2 [8 + 42] = 15/2 × 50 = 375.", listOf("S15 = 375 (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "මෙම රටාවේ 94 ලබාදෙන්නේ කීවෙනි පදයෙන්දැයි ගණනය කරන්න.", 4, "3n + 1 = 94 ⇒ 3n = 93 ⇒ n = 31.", listOf("31 වන පදය (ලකුණු 4)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "(2x + 3)(x + 4) වීජීය ප්‍රකාශනය ප්‍රසාරණය කර සුළු කරන්න.", 3, "2x² + 8x + 3x + 12 = 2x² + 11x + 12.", listOf("2x² + 11x + 12 (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "x² - 16y² වර්ග දෙකක වෙනස සාධක වෙන් කරන්න.", 4, "(x - 4y)(x + 4y).", listOf("සාධක වෙන් කිරීම (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "3x² + 10x + 8 ත්‍රිපද වර්ගජ ප්‍රකාශනයේ සාධක සොයන්න.", 4, "3x² + 6x + 4x + 8 = 3x(x + 2) + 4(x + 2) = (3x + 4)(x + 2).", listOf("(3x + 4)(x + 2) (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "x² - 5x + 6 = 0 වර්ගජ සමීකරණය විසඳා x හි අගයන් ලබාගන්න.", 4, "(x - 2)(x - 3) = 0 ⇒ x = 2 හෝ x = 3.", listOf("x = 2, x = 3 (ලකුණු 4)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "3x + 5 = 26 සරල ඒකජ සමීකරණය විසඳා x හි අගය සොයන්න.", 3, "3x = 21 ⇒ x = 7.", listOf("x = 7 (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "3x + 2y = 16 සහ 2x + y = 9 සමගාමී සමීකරණ යුගලය විසඳන්න.", 4, "දෙවන සමීකරණය 2න් ගුණ කර: 4x + 2y = 18. අඩු කළ විට: x = 2. y = 5.", listOf("x = 2, y = 5 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "පොතක සහ පෑනක මුළු මිල රු. 150කි. පොත් 2ක සහ පෑන් 3ක මිල රු. 360ක් නම් එක් එකෙහි මිල සොයන්න.", 4, "x + y = 150 සහ 2x + 3y = 360 ⇒ x = 90, y = 60.", listOf("පොත = රු.90, පෑන = රු.60 (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "සමගාමී සමීකරණ ප්‍රස්තාරිකව විසඳීමේදී ඡේදන ලක්ෂ්‍යයේ ඛණ්ඩාංකයෙන් ලැබෙන විසඳුම පැහැදිලි කරන්න.", 4, "ඡේදන ලක්ෂ්‍යය (x, y) යනු සමීකරණ දෙකම එකවර තෘප්ත කරන එකම විසඳුමයි.", listOf("ඡේදන ලක්ෂ්‍ය අර්ථය (ලකුණු 4)"))
      )
      4 -> listOf(
        StructuredSubQuestion("(i)", "2³ × 2⁵ / 2⁴ දර්ශක නීති භාවිතයෙන් සුළු කරන්න.", 3, "2^(3+5-4) = 2⁴ = 16.", listOf("16 (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "log₂ 32 = 5 දර්ශක ස්වරූපයෙන් දක්වන්න.", 4, "2⁵ = 32.", listOf("2⁵ = 32 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "ලඝුගණක නීති භාවිතයෙන් log (x²) + log (y) - log (z) එකම ලඝුගණකයක් ලෙස ලියන්න.", 4, "log (x²y / z).", listOf("log (x²y / z) (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "ලඝුගණක වගුව භාවිතයෙන් √(45.6 × 2.34) අගය සොයන්න.", 4, "log අගයන් ලබාගෙන 2න් බෙදා ප්‍රතිලඝුගණකය (antilog) සෙවීම.", listOf("ලඝුගණක ගණනය (ලකුණු 4)"))
      )
