        StructuredSubQuestion("(iv)", "ස්වාධීන සිදුවීම් A සහ B සඳහා P(A ∩ B) = P(A) × P(B) සූත්‍රයෙන් ගණනය කරන්න.", 4, "සම්භාවිතා ගුණ කර අවසන් පිළිතුර ලබාගැනීම.", listOf("ස්වාධීන සිදුවීම් (ලකුණු 4)"))
      )
      else -> listOf(
        StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) කුලක දෙකක් සඳහා n(A ∪ B) = n(A) + n(B) - n(A ∩ B) සූත්‍රය ලියන්න.", 3, "කුලක මූලික සූත්‍රය නිවැරදිව දැක්වීම.", listOf("කුලක සූත්‍රය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "වෙන් රූප සටහනක දත්ත ඇතුළත් කර අඥාත x හි අගය සොයන්න.", 4, "වෙන් රූපය ඇඳ අදාළ කලාපවල සංඛ්‍යා සටහන් කර x සෙවීම.", listOf("x සෙවීම (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "කුලක 3ක් සහිත වෙන් රූප ගැටලුවක පොදු ඡේදනය A ∩ B ∩ C සෙවීම.", 4, "පියවරෙන් පියවර කලාප අගයන් එකතු කර ඡේදනය සෙවීම.", listOf("පොදු ඡේදනය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "A කුලකයේ පූරක කුලකය A' වෙන් රූප සටහනේ පාට කර දක්වන ආකාරය විස්තර කරන්න.", 4, "A කුලකයෙන් පිටත සර්වත්‍ර කුලකය තුළ ඇති ප්‍රදේශය පාට කිරීම.", listOf("පූරක කුලකය (ලකුණු 4)"))
      )
    }
  }

  // =================================================================================
  // 3. HISTORY (ඉතිහාසය)
  // =================================================================================
  private fun getHistorySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    return when (q % 12) {
      1 -> listOf(
        StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) අධ්‍යයනයට භාවිත වන ප්‍රධාන සාහිත්‍ය මූලාශ්‍ර 2ක් නම් කරන්න.", 3, "1. මහාවංශය / දීපවංශය.\n2. පූජාවලිය / රාජාවලිය / ඡූලවංශය.", listOf("සාහිත්‍ය මූලාශ්‍ර 2 (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "මෙම යුගය තහවුරු කරන ප්‍රධාන පුරාවිද්‍යාත්මක මූලාශ්‍ර 2ක් ලියන්න.", 4, "1. සෙල්ලිපි (ලෙන් ලිපි/ටැම් ලිපි).\n2. කාසි, මැටි බඳුන් හා ගොඩනැගිලි අවශේෂ.", listOf("පුරාවිද්‍යා මූලාශ්‍ර 2 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "පුරාවිද්‍යාත්මක මූලාශ්‍ර සාහිත්‍ය මූලාශ්‍රවලට වඩා විශ්වාසදායක වීමට හේතුව පැහැදිලි කරන්න.", 4, "සමකාලීනව නිර්මාණය වූ, පසුකාලීනව වෙනස් කළ නොහැකි භෞතික සාක්ෂි වන බැවින්.", listOf("විශ්වාසදායක බව (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "විදේශීය වාර්තාකරුවන්ගේ (උදා: පාහියන් හිමි, ඉබ්න් බතුතා) වාර්තාවල ඇති වැදගත්කම ලියන්න.", 4, "මෙරට සමාජීය, ආර්ථික හා දේශපාලනික තත්ත්වයන් අපක්ෂපාතීව සටහන් වී තිබීම.", listOf("විදේශ වාර්තා වැදගත්කම (ලකුණු 4)"))
      )
      2 -> listOf(
        StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) යුගයට අදාළ ප්‍රධාන පාලකයා සහ රාජධානි මධ්‍යස්ථානය නම් කරන්න.", 3, "ප්‍රධාන පාලකයාගේ නම සහ අගනගරය (අනුරාධපුරය/පොළොන්නරුව/කෝට්ටේ/මහනුවර).", listOf("පාලකයා සහ අගනුවර (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "එම පාලකයා විසින් ඉටුකරන ලද ප්‍රධාන රාජ්‍ය/ශාසනික සේවාවන් 2ක් ලියන්න.", 4, "1. විශාල වාරි කර්මාන්ත හා වැව් කරවීම.\n2. වෙහෙර විහාර ඉදිකිරීම සහ රාජ්‍යය එක්සේසත් කිරීම.", listOf("සේවාවන් 2 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "එම යුගයේ පැවති පරිපාලන ව්‍යුහයේ ප්‍රධාන ලක්ෂණයක් පැහැදිලි කරන්න.", 4, "රජු කේන්ද්‍ර කරගත් මධ්‍යගත පාලනය සහ රට කරවන ඇමතිවරුන්ගේ දායකත්වය.", listOf("පරිපාලන ලක්ෂණය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "මෙම යුගයේ අවසානයට බලපෑ ප්‍රධාන හේතුවක් දක්වන්න.", 4, "දකුණු ඉන්දීය ආක්‍රමණ, අභ්‍යන්තර බල අරගල හෝ විදේශීය යටත්විජිත බලපෑම්.", listOf("අවසානයට බලපෑ හේතුව (ලකුණු 4)"))
      )
      3 -> listOf(
        StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) සමයේ ඉදිකරන ලද විශිෂ්ට වාරි නිර්මාණයක් නම් කරන්න.", 3, "පරාක්‍රම සමුද්‍රය, කලා වැව, මින්නේරිය වැව හෝ ජය ගඟ.", listOf("වාරි නිර්මාණය (ලකුණු 3)")),
        StructuredSubQuestion("(ii)", "අතීත ජල කළමනාකරණ පද්ධතියේ ප්‍රධාන ඉංජිනේරු අංග 2ක් ලියන්න.", 4, "1. බිසෝකොටුව (ජල පීඩනය පාලනය කිරීම).\n2. සූරිය වැව / රළපනාව / පිටවාන.", listOf("ඉංජිනේරු අංග 2 (ලකුණු 4)")),
        StructuredSubQuestion("(iii)", "අතීත වාරි ශිෂ්ටාචාරයේ 'වැවයි දාගැබයි' සංකල්පයේ අර්ථය පැහැදිලි කරන්න.", 4, "ගමේ ආර්ථික සර්වප්‍රකාර සංවර්ධනය වැවෙන් ද ආධ්‍යාත්මික සංවර්ධනය දාගැබෙන් ද සිදුවීම.", listOf("වැවයි දාගැබයි සංකල්පය (ලකුණු 4)")),
        StructuredSubQuestion("(iv)", "වර්තමාන කෘෂිකර්මාන්තයට අතීත වාරි ශිෂ්ටාචාරයෙන් ගත හැකි ආදර්ශයක් ලියන්න.", 4, "පරිසර හිතකාමී ලෙස ජල සම්පත කළමනාකරණය කිරීම සහ සංරක්ෂණය.", listOf("අනාගත ආදර්ශය (ලකුණු 4)"))
      )
