  // =================================================================================
  private fun getGeographySubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) භූගෝලීය සංකල්පය හෝ භූමිරූපය නිර්වචනය කරන්න.", 3, "ශ්‍රී ලංකාවේ භූගෝලීය O/L විෂය නිර්දේශයට අනුව පැහැදිලි අර්ථ දැක්වීම.", listOf("භූගෝලීය නිර්වචනය (ලකුණු 3)")),
      StructuredSubQuestion("(ii)", "ශ්‍රී ලංකාවේ අදාළ ලක්ෂණය පිහිටි ප්‍රදේශ 2ක් නම් කරන්න.", 4, "1. මධ්‍යම කඳුකර ප්‍රදේශය / තෙත් කලාපය.\n2. වියළි කලාපය / වෙරළබඩ තීරය.", listOf("ප්‍රදේශ 2 නම් කිරීම (ලකුණු 4)")),
      StructuredSubQuestion("(iii)", "මෙම සංසිද්ධිය නිසා මානව ක්‍රියාකාරකම්වලට සිදුවන බලපෑම ලියන්න.", 4, "කෘෂිකර්මාන්තයට, ජල සම්පතට සහ ජනාවාස ව්‍යාප්තියට සිදුවන බලපෑම.", listOf("මානව බලපෑම (ලකුණු 4)")),
      StructuredSubQuestion("(iv)", "පරිසර හිතකාමී ලෙස භූමිය කළමනාකරණය කරගන්නා ආකාරය ලියන්න.", 4, "පාංශු සංරක්ෂණය සහ වනාන්තර සංරක්ෂණ ක්‍රමවේද යොදාගැනීම.", listOf("පරිසර කළමනාකරණය (ලකුණු 4)"))
    )
  }

  // =================================================================================
  // 9. CIVICS (පුරවැසි අධ්‍යාපනය)
  // =================================================================================
  private fun getCivicsSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) පුරවැසි සංකල්පය හෝ ව්‍යවස්ථාපිත ප්‍රතිපාදනය දක්වන්න.", 3, "ප්‍රජාතන්ත්‍රවාදී අයිතිවාසිකම් සහ යුතුකම් O/L මට්ටමෙන් දක්වීම.", listOf("සංකල්පය දැක්වීම (ලකුණු 3)")),
      StructuredSubQuestion("(ii)", "ඊට අදාළ ප්‍රධාන රාජ්‍ය ආයතන 2ක් නම් කරන්න.", 4, "1. පාර්ලිමේන්තුව / ශ්‍රේෂ්ඨාධිකරණය.\n2. පළාත් සභාව / ප්‍රදේශීය සභාව.", listOf("රාජ්‍ය ආයතන 2 (ලකුණු 4)")),
      StructuredSubQuestion("(iii)", "යහපත් පුරවැසියෙකු ලෙස ඉටු කළ යුතු මූලික වගකීම් 2ක් ලියන්න.", 4, "1. නීතියට ගරු කිරීම සහ මහජන දේපළ ආරක්ෂා කිරීම.\n2. සමාජීය සංහිඳියාව රැකගැනීම.", listOf("වගකීම් 2 (ලකුණු 4)")),
      StructuredSubQuestion("(iv)", "ජාතික සංවර්ධනයට යහපත් පුරවැසියාගේ දායකත්වය ලියන්න.", 4, "සාමය, නිෂ්පාදන කර්තව්‍යය සහ සදාචාරාත්මක සමාජයක් බිහිකිරීම.", listOf("ජාතික දායකත්වය (ලකුණු 4)"))
    )
  }

  // =================================================================================
  // 10. COMMERCE (ව්‍යාපාර හා ගිණුම්කරණය)
  // =================================================================================
  private fun getCommerceSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) ව්‍යාපාරික සංකල්පය හෝ ගිණුම්කරණ සමීකරණය ලියන්න.", 3, "වත්කම් = හිමිකම + වගකීම් (Assets = Capital + Liabilities).", listOf("සමීකරණය (ලකුණු 3)")),
      StructuredSubQuestion("(ii)", "ව්‍යාපාරයක මූලික අරමුණු 2ක් ලියන්න.", 4, "1. ලාභ ඉපැයීම.\n2. සමාජීය වගකීම් ඉටුකිරීම සහ පාරිභෝගික තෘප්තිය.", listOf("අරමුණු 2 (ලකුණු 4)")),
      StructuredSubQuestion("(iii)", "ද්විත්ව සටහන් තැබීමේ මූලධර්මය පැහැදිලි කරන්න.", 4, "සෑම ගනුදෙනුවකම හර සහ බැර පැති සමානව සටහන් කිරීම.", listOf("ද්විත්ව සටහන් (ලකුණු 4)")),
      StructuredSubQuestion("(iv)", "මූල්‍ය තත්ත්ව ප්‍රකාශනයේ ඇති වැදගත්කම දක්වන්න.", 4, "ව්‍යාපාරයේ වත්කම්, වගකීම් හා හිමිකම් තත්ත්වය නිවැරදිව පෙන්වීම.", listOf("මූල්‍ය තත්ත්වය (ලකුණු 4)"))
    )
  }

  // =================================================================================
  // 11. GENERAL FALLBACK
  // =================================================================================
  private fun getGeneralSubQuestions(grade: String, theme: String, q: Int, setNumber: Int): List<StructuredSubQuestion> {
    return listOf(
      StructuredSubQuestion("(i)", "$theme ($grade ශ්‍රේණිය) මූලික සංකල්පය සහ අර්ථ නිරූපණය ලියන්න.", 3, "විෂයානුබද්ධ අර්ථ නිරූපණය නිවැරදිව දක්වීම.", listOf("අර්ථ නිරූපණය (ලකුණු 3)")),
      StructuredSubQuestion("(ii)", "ඊට අදාළ ප්‍රධාන සාධක හෝ ලක්ෂණ 2ක් ලියන්න.", 4, "1. පළමු ප්‍රධාන සාධකය.\n2. දෙවන ප්‍රධාන සාධකය.", listOf("සාධක 2 (ලකුණු 4)")),
      StructuredSubQuestion("(iii)", "එදිනෙදා ජීවිතයේදී මෙම විෂය දැනුම යොදාගන්නේ කෙසේද?", 4, "ප්‍රායෝගික ගැටලු විසඳීමට සහ නිවැරදි තීරණ ගැනීමට.", listOf("ප්‍රායෝගික යෙදුම (ලකුණු 4)")),
      StructuredSubQuestion("(iv)", "විභාග සාර්ථක කරගැනීමට මෙම ඒකකය ප්‍රගුණ කිරීමේ ඇති වැදගත්කම ලියන්න.", 4, "සම්පූර්ණ ලකුණු ලබාගැනීමට සහ විෂය දැනුම වර්ධනය කරගැනීමට.", listOf("විභාග වැදගත්කම (ලකුණු 4)"))
    )
  }
}
